num = 3
if num > 0:
    print(num, "- positive number")
print("Next line")

num = -1
if num > 0:
    print(num, "- positive number")
else:
    print(num, "- negative number or zero")
print("Next line")

num = 0
if num > 0:
    print(num, "- positive number")
elif num == 0:
    print(num, "- zero")
else:
    print(num, "- negative number")
print("Next line")

      # Инструкция break прерывает цикл, в котором он объявлен.
for val in "stroka":
    if val == "o":
        break
    print(val)

print("End")

# Инструкция continue используется для того, чтобы пропустить оставшееся тело цикла текущей итерации.
# Цикл не завершается, а продолжается со следующей итерации.

for val in "stroka":
    if val == "o":
        continue
    print(val)

print("End")

# Инструкция pass — «пустой» оператор. В Python у циклов и функций не может быть «пустого» тела
# — интерпретатор выведет ошибку. Поэтому в тело можно поместить инструкцию pass, и все заработает.

sequence = {'p', 'a', 's', 's'}
for val in sequence:
    pass

# Точно так же можно делать с пустой функцией или классом:

def function(args):
    pass

class Example:
    pass

""" clear() Удаляет все элементы из словаря copy() Возвращает неглубокую копию словаря fromkeys(seq[, v]) Возвращает словарь с ключами из seq и значениями, равными v (по умолчанию None) get(key[,d]) Возвращает значение ключа key. Если key не существует, возвращает d (по умолчанию None) items() Возвращает новый объект элементов словаря в формате (ключ, значение) keys() Возвращает новый объект с ключами словаря pop(key[,d]) Удаляет элемент с ключом key и возвращает его значение или d, если key не найден. Если d не было обозначено и key не найден, вызывает ошибку KeyError. popitem() Удаляет и возвращает произвольную пару (ключ, значение). Вызывае ошибку KeyError, если словарь пустой. setdefault(key[,d]) Если ключ key есть в словаре, возвращает соответствующее ему значение. Если нет, добавляет в словарь элемент с ключом key и значением d и возвращает d (по умолчанию None) update([other]) Обновляет словарь имеющимися парами ключ/значение из other, перезаписывая существующие ключи values() Возвращает новый объект со значениями словаря """ marks = {}.fromkeys(['mathematics', 'Russian language', 'physics'], 0) print(marks)
for item in marks.items(): print(item) print(list(sorted(marks.keys())))
""" all() Возвращает True, если все ключи словаря = True (или если словарь пуст) any() Возвращает True, если хотя бы один ключ словаря = True. Если словарь пуст, возвращает False. len() Возвращает длину (количество элементов) словаря cmp() Сравнивает элементы двух словарей (не работает в Python 3) sorted() Возвращает новый список с отсортированными ключами словаря """ squares = {0: 0, 1: 1, 3: 9, 5: 25, 7: 49, 9: 81}
print(all(squares)) print(any(squares)) print(len(squares)) print(sorted(squares))

# Создаем класс и его объекты class Parrot:
# атрибуты класса species = "bird"
# атрибуты экземпляра def __init__(self, name, age): self.name = name self.age = age
# создаем экземпляра класса kesha = Parrot("Kesha", 10) cookie = Parrot("Kuki", 15)
# получаем доступ к атрибутам класса print("Kesha - {}".format(kesha.__class__.species)) print("Kuki also {}".format(cookie.__class__.species))
# получаем доступ к атрибутам экземпляра print("{} - {}-years old parrot".format(kesha.name, kesha.age)) print("{} - {}-years old parrot".format(cookie.name, cookie.age))
""" Мы создали класс Parrot. После этого мы объявили атрибуты — характеристики объекта. Атрибуты объявлены внутри класса — в методе __init__. Это метод-инициализатор, который запускается сразу же после создания объекта. После этого мы создаем экземпляры класса Parrot. kesha и cookie — ссылки на (значения) наши новые объекты. Получить доступ к атрибуту класса можно так — __class__.species. Атрибуты класса для всех экземпляров класса одинаковы. Точно так же мы можем получить доступ к атрибутам экземпляра — kesha.name и kesha.age. Но вот атрибуты каждого экземпляра класса уникальны. """
# Создаем метод class Parrot:
# атрибуты экземпляра def __init__(self, name, age): self.name = name self.age = age
# метод экземпляра def sing(self, song): return "{} sing {}".format(self.name, song)
def dance(self): return "{} dance".format(self.name)
# создаем экземпляр класса kesha = Parrot("Kesha", 10)
# вызываем методы экземпляра print(kesha.sing("songs")) print(kesha.dance())
""" Наследование — способ создания класса. Его суть заключается в том, что функциональность нового класса наследуются от уже существующего класса. Новый класс называется производным (дочерним). Существующий — базовым (родительским). """ # родительский класс class Bird:
def __init__(self): print("The bird is ready")
def whoisThis(self): print("Bird")
def swim(self): print("Swim faster")
# дочерний класс class Penguin(Bird):
def __init__(self): # вызов функции super() super().__init__() print("The penguin is ready")
def whoisThis(self): print("Penguin")
def run(self): print("Run fuster")
peggy = Penguin() peggy.whoisThis() peggy.swim() peggy.run()
""" Инкапсуляция Мы можем ограничить доступ к методам и переменным, что предотвратит модификацию данных — это и есть инкапсуляция. Приватные атрибуты выделяются нижним подчеркиванием: одинарным _ или двойным __. """ class Computer:
def __init__(self): self.__maxprice = 900
def sell(self): print("Sale price: {}".format(self.__maxprice))
def setMaxPrice(self, price): self.__maxprice = price
c = Computer() c.sell()
# изменение цены c.__maxprice = 1000 c.sell()
# используем функцию изменения цены c.setMaxPrice(1000) c.sell()
""" Мы использовали метод __init__() для хранения максимальной цены компьютера. Затем мы попытались изменить цену — безуспешно: Python воспринимает __maxprice как приватный атрибут. Как видите, для изменения цены нам нужно использовать специальную функцию — setMaxPrice(), которая принимает цену в качестве параметра. """
""" Полиморфизм — особенность ООП, позволяющая использовать одну функцию для разных форм (типов данных). Допустим, нам нужно закрасить фигуру. Их форма может быть любой: прямоугольник, квадрат, круг. Одним и тем же методом мы можем раскрасить любую фигуру. Такой принцип и называется полиморфизмом. """ class Parrot:
def fly(self): print("Parrot can fly")
def swim(self): print("Parrot can not swim")
class Penguin:
def fly(self): print("Penguin can not fly")
def swim(self): print("Penguin can swim")
# общий интерфейс def flying_test(bird): bird.fly()
# создаем экземпляров класса kesha = Parrot() peggy = Penguin()
# передача объектов в качестве аргумента flying_test(kesha) flying_test(peggy)

      #

class Pizza:
    def __init__(self, ingredients):
        self.ingredients = ingredients
    def __repr__(self):
        return f'Pizza({self.ingredients!r})'
    @classmethod
    def margherita(cls):
        return cls(['моцарелла', 'помидоры'])
    @classmethod
    def prosciutto(cls):
        return cls(['моцарелла', 'помидоры', 'ветчина'])

    @staticmethod
    def some_method():
        return 'Static'

print( Pizza.margherita() )
print( Pizza.prosciutto() )
print( Pizza.some_method() )
